def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]
    change = new_value - old_value

    return {
        "value": change,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": "shares"
            }
        }
    }
